import{_ as t,o,c as r,ag as a}from"./chunks/framework.BIas3y6W.js";const f=JSON.parse('{"title":"Week 16 — Project Fair","description":"","frontmatter":{"source":"weeks/16-project-fair/README.md"},"headers":[],"relativePath":"weeks/16-project-fair/index.md","filePath":"weeks/16-project-fair/index.md"}'),s={name:"weeks/16-project-fair/index.md"};function n(i,e,h,l,d,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="week-16--project-fair" tabindex="-1">Week 16 — Project Fair <a class="header-anchor" href="#week-16--project-fair" aria-label="Permalink to &quot;Week 16 — Project Fair&quot;">​</a></h1><blockquote><p>You hand in a version you can stand behind, real people try it, and you reflect on what you can actually explain.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><p>Week 16 is finals week. There are no regular studios, no lab and no homework: just the Project Fair and the final submission.</p><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>When</strong></td><td>The Project Fair runs in the course&#39;s scheduled 2-hour final exam slot (University Regulation H-1-b): [day, time and room, posted on Canvas]</td></tr><tr><td><strong>Before the Fair</strong></td><td>App live, Supabase awake, sign made, pitch practiced; <code>v1.0</code> release made and the product submitted on Canvas (<a href="#before-class">checklist</a>)</td></tr><tr><td><strong>At the Fair (2 hours)</strong></td><td>Gallery walk in two rounds · spotlight demos · read your feedback cards · post-course self-assessment (🔴 AI off, Canvas) · course retrospective · awards and closing</td></tr><tr><td><strong>After the Fair</strong></td><td>Revise your personal AI-use rules (🔴 AI off, Canvas) · final reflection (🔴 AI off, Canvas), using your Fair feedback</td></tr><tr><td><strong>Due: the final submission</strong></td><td><strong>Product</strong> (production URL and screenshot, <code>v1.0</code> release, demo video): at the start of the Project Fair. <strong>Final reflection and revised AI-use rules:</strong> 11:59 pm on the last day of finals week. Both fall before the University&#39;s grade deadline (<a href="#final-submission">checklist</a>)</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: last fixes before you freeze <code>v1.0</code>, in the Safe Loop · 🔴 AI off: feedback cards, the self-assessment, retrospective notes, your revised AI-use rules, the final reflection</td></tr><tr><td><strong>Must read</strong></td><td>README (this page), the <a href="./project-fair.html">Project Fair guide</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./../../projects/capstone.html#what-done-means">What &quot;done&quot; means</a> · <a href="./../15-ship-it/polish-checklist.html">Polish checklist</a> · <a href="./../../templates/REFLECTION.html">REFLECTION.md template</a> · <a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a> · <a href="./../../resources/accessibility.html">Accessibility guide</a></td></tr><tr><td><strong>Minimum to finish</strong></td><td>A production URL where your main user story works, a <code>v1.0</code> release, and walkthrough 3 (done in week 14). Everything else adds points; these three are what the course can&#39;t grade without</td></tr><tr><td><strong>Time</strong></td><td>Before the Fair about 1 h · the Fair 2 h · after the Fair about 2 h</td></tr></tbody></table><p>Canvas is the course&#39;s learning management system. Your self-assessment, AI-use rules and final reflection go there, never in a repo.</p><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li><strong>Present</strong> a project in 60–90 seconds, then hand it over so a stranger can use it.</li><li>Turn what users found into <strong>honest evidence</strong> about your app and your own understanding.</li><li><strong>Freeze</strong> what you submit with a release (<code>v1.0</code>) that matches your README.</li><li><strong>Compare</strong> how much you felt you understood with what you could actually explain, and revise your own AI-use rules with evidence.</li><li>Plan how you&#39;ll <strong>keep the skill</strong> after the course.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><p>Before the Fair:</p><ul><li>☐ Open your <strong>production URL</strong> in a private window, on a phone and a laptop, and check the main user story works.</li><li>☐ <strong>Freeze and submit the product</strong> (<a href="#1-make-the-v10-release-10-min">steps 1–2 below</a>): make the <code>v1.0</code> release on your final commit and submit the links on Canvas before the Fair starts.</li><li>☐ Open your Supabase project, if you have one, <strong>the day before</strong>, and restore it if it&#39;s paused (<a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a>).</li><li>☐ Make a sign or sticky note with your app&#39;s name and its production URL or a QR code.</li><li>☐ Practice your 60–90 second pitch: problem → quick demo → one thing you&#39;re proud of → <strong>one known issue</strong>.</li><li>☐ Queue your demo video as a backup, open your Known issues section in a tab, and charge your laptop.</li><li>☐ Use made-up data only, and ask visitors to do the same.</li></ul><h2 id="the-project-fair" tabindex="-1">The Project Fair <a class="header-anchor" href="#the-project-fair" aria-label="Permalink to &quot;The Project Fair&quot;">​</a></h2><p>The Fair fills the whole 2-hour final exam slot. The <a href="./project-fair.html">Project Fair guide</a> has the format, the run sheet, the voting categories and the feedback card.</p><table tabindex="0"><thead><tr><th>Time</th><th>What</th></tr></thead><tbody><tr><td>0:00–0:10</td><td>Set up your station; your instructor explains the format and splits the class into two groups</td></tr><tr><td>0:10–1:05</td><td><strong>Two rounds:</strong> present while the other group visits, then swap</td></tr><tr><td>1:05–1:15</td><td>Spotlight demos (3 projects)</td></tr><tr><td>1:15–1:20</td><td>Read the feedback cards you received</td></tr><tr><td>1:20–1:35</td><td>Post-course self-assessment (🔴 AI off, Canvas)</td></tr><tr><td>1:35–1:50</td><td>Course retrospective</td></tr><tr><td>1:50–2:00</td><td>Awards and closing</td></tr></tbody></table><p><strong>At your station:</strong> give your pitch when a visitor arrives, then <strong>hand the app over</strong> and let them try it. If the live app hiccups, play the video.</p><p><strong>When you visit:</strong> try the app yourself, ask one question, and fill in a <a href="./project-fair.html">feedback card</a> (🔴 AI off; a printed card or the digital form). Vote with the slips you&#39;re given, for projects other than your own. Keep the cards you receive: they&#39;re honest user feedback, and the evidence for your final reflection. What visitors find after the freeze goes into your reflection, not into the graded version.</p><p><strong>Post-course self-assessment (15 min, 🔴 AI off).</strong> Complete the <a href="./../../assessment/self-assessment.html">post-course self-assessment</a> on Canvas. It pairs with the one you took in week 1, so you can see what changed. Answer honestly: it isn&#39;t graded on the answers.</p><p><strong>Course retrospective (15 min).</strong> Your feedback shapes the next cohort. It&#39;s anonymous and not graded.</p><ol><li><strong>Write (5 min), on your own:</strong> one thing to <strong>keep</strong>, one to <strong>change</strong>, one to <strong>drop</strong>, on the sticky notes or anonymous form your instructor gives you.</li><li><strong>Group (7 min):</strong> the class sorts the notes into themes and talks through the biggest ones. Say what happened, not who.</li><li><strong>Advice to the next cohort (3 min):</strong> one sentence you&#39;d tell someone starting week 1. With your permission, your instructor may share these anonymously with the next cohort.</li></ol><p><strong>Can&#39;t be there?</strong> If you miss the Fair for a reason the University recognizes (Regulations M-1 and M-3), tell your instructor as early as you can; they&#39;ll arrange a make-up (<a href="./../../assessment/#absences-and-make-up-work">Absences and make-up work</a>). <strong>Working alone?</strong> The Fair becomes a public demo slot your instructor arranges (a department seminar, a lab meeting or invited staff), plus three outside testers using the feedback card on made-up data, with no voting; the retrospective becomes a short conversation with your instructor (<a href="./../../resources/self-paced.html">Self-paced path</a>).</p><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><ul><li><a href="./project-fair.html">Project Fair guide</a>: format, run sheet, peer voting, feedback cards, accessibility, online and small-class versions</li><li><a href="./../15-ship-it/polish-checklist.html">Polish checklist</a>, for last fixes</li><li>Templates: <a href="./../../templates/REFLECTION.html">REFLECTION.md template</a> and your capstone&#39;s README, <code>SPEC.md</code>, <code>AGENTS.md</code>, <code>PROMPTS.md</code>, <code>TESTS.md</code> and <code>SECURITY_CHECKLIST.md</code></li></ul><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p><strong>Users find what you can&#39;t.</strong> You&#39;ve used your app hundreds of times, always the same way. A visitor uses it once, differently, with no one explaining it. The feedback card&#39;s last question, &quot;Did it work from the app alone, with no help?&quot;, is the real test of done.</p><p><strong>A release is a promise.</strong> A <a href="./../../resources/glossary.html#release">release</a> tagged <code>v1.0</code> marks exactly the commit you submit. Graders look at that commit, so a later push can&#39;t break what you handed in, and your README must describe that version honestly.</p><p><strong>Feeling fast isn&#39;t the same as understanding.</strong> In a 2025 study, experienced open-source developers were 19% slower with AI while believing they were faster (<a href="https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/" target="_blank" rel="noreferrer">METR</a>); METR&#39;s later estimates point in different directions (<a href="https://metr.org/blog/2026-02-24-uplift-update/" target="_blank" rel="noreferrer">METR 2026</a>). The walkthroughs and the final reflection exist for that gap: the reflection asks you to measure it in your own work.</p><p><strong>Rules you write for yourself work.</strong> In a seven-week pilot, students who had written their own rules for when to use AI did better (<a href="https://arxiv.org/abs/2609.16784" target="_blank" rel="noreferrer">Azimi</a>). You wrote yours in week 2. Now you can revise them with evidence instead of guesses.</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><p>The <strong>final reflection</strong> is this week&#39;s understanding check: with the AI off, you compare how much you <em>felt</em> you understood while building with what you could <em>actually explain</em> afterward, in walkthroughs, the AI-off maintenance task and at the Fair. Its prompts are <a href="#4-write-your-final-reflection-about-15-h-after-the-fair">below</a>.</p><h2 id="final-submission" tabindex="-1">Final submission <a class="header-anchor" href="#final-submission" aria-label="Permalink to &quot;Final submission&quot;">​</a></h2><p>Your capstone is done when every box is ticked. The product is frozen <strong>before</strong> the Fair; the writing comes after it.</p><ul><li>☐ <strong>Took part in the Project Fair</strong> (presented and visited), or did the make-up your instructor arranged.</li><li>☐ <strong>Before the Fair:</strong> everything in <a href="./../../projects/capstone.html#what-done-means">What &quot;done&quot; means</a> is true, including the <a href="./../15-ship-it/homework.html">week 15 deliverables</a>.</li><li>☐ <strong>Before the Fair:</strong> release <code>v1.0</code> on your final commit.</li><li>☐ <strong>Before the Fair, on Canvas:</strong> the repo URL, the <strong>production URL with a screenshot</strong> of the app working there, the <code>v1.0</code> release link, and the demo video link (or the video itself). Pairs: the signed contribution statement.</li><li>☐ <strong>Post-course self-assessment</strong> on Canvas (🔴 AI off), at the Fair.</li><li>☐ <strong>By 11:59 pm on the last day of finals week:</strong> revised personal AI-use rules on Canvas (🔴 AI off).</li><li>☐ <strong>By the same deadline:</strong> final reflection on Canvas (🔴 AI off, 400–600 words), with your revised rules.</li></ul><h3 id="the-final-milestone" tabindex="-1">The final milestone <a class="header-anchor" href="#the-final-milestone" aria-label="Permalink to &quot;The final milestone&quot;">​</a></h3><p>The row below is copied word for word from the <a href="./../../projects/capstone.html#milestones">capstone milestones</a>:</p><table tabindex="0"><thead><tr><th>Milestone</th><th>Due</th><th>Deliverables</th><th>Graded as</th></tr></thead><tbody><tr><td><strong>Final</strong> (finals week)</td><td><strong>Product</strong> (production URL and screenshot, <code>v1.0</code> release, demo video): at the start of the Project Fair. <strong>Final reflection</strong>, with your revised AI-use rules: 11:59 pm on the last day of finals week. Both are on Canvas, before the University&#39;s grade deadline</td><td>• Everything in <a href="./../../projects/capstone.html#what-done-means">What done means</a><br>• A GitHub release <strong><code>v1.0</code></strong> on your final commit<br>• On Canvas: the <strong>production URL and a screenshot</strong> of it working, the repo URL and the link to the <code>v1.0</code> release<br>• A 2–3 minute <a href="./../../projects/capstone.html#demo-video">demo video</a>, linked from the README or submitted on Canvas<br>• Your <a href="./../../projects/capstone.html#final-reflection">final reflection</a> on Canvas (🔴 AI off), with your revised personal AI-use rules</td><td><a href="./../../assessment/rubrics.html#capstone">Capstone rubric</a>; the final reflection in <a href="./../../assessment/rubrics.html#reflections-and-peer-reviews">Reflections and peer reviews</a></td></tr></tbody></table><h3 id="1-make-the-v10-release-10-min" tabindex="-1">1. Make the <code>v1.0</code> release (10 min) <a class="header-anchor" href="#1-make-the-v10-release-10-min" aria-label="Permalink to &quot;1. Make the `v1.0` release (10 min)&quot;">​</a></h3><p>Do this <strong>before the Fair</strong>, after your last commit, so graders see exactly what you submit. First run <code>npm test</code> and <code>npm run check:secrets</code>, check the production URL in a private window, and make sure the README, <code>SPEC.md</code> status and <code>SECURITY_CHECKLIST.md</code> match the app. On your repo&#39;s GitHub page: <strong>Releases → Draft a new release</strong> (or <strong>Create a new release</strong>) → <strong>Choose a tag</strong>, type <code>v1.0</code> and choose to create it on publish, target <code>main</code> → title it <code>v1.0</code>, add a one-line summary → <strong>Publish release</strong>. Menus move; if you can&#39;t find it, ask your assistant how to create a GitHub release.</p><h3 id="2-submit-the-product-on-canvas-10-min-before-the-fair" tabindex="-1">2. Submit the product on Canvas (10 min, before the Fair) <a class="header-anchor" href="#2-submit-the-product-on-canvas-10-min-before-the-fair" aria-label="Permalink to &quot;2. Submit the product on Canvas (10 min, before the Fair)&quot;">​</a></h3><p>Submit the links in the checklist above before the Fair starts. The final reflection and the AI-use rules are their own Canvas assignments, due after the Fair.</p><p>Grading: the <a href="./../../assessment/rubrics.html#capstone">capstone rubric</a>. A working demo is required but not sufficient: spec, tests, security, process, documentation and the code you can explain all count.</p><h3 id="3-revise-your-personal-ai-use-rules-about-30-min-after-the-fair" tabindex="-1">3. Revise your personal AI-use rules (about 30 min, after the Fair) <a class="header-anchor" href="#3-revise-your-personal-ai-use-rules-about-30-min-after-the-fair" aria-label="Permalink to &quot;3. Revise your personal AI-use rules (about 30 min, after the Fair)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> In week 2 you wrote your own rules for when you use AI and when you don&#39;t; you now have a semester of evidence. Open your week 2 rules on Canvas.</p><ol><li>For each rule: <strong>keep</strong>, <strong>change</strong> or <strong>drop</strong> it, with one piece of evidence from the course (a walkthrough, the AI-off maintenance task, a bug you caught, a time you over-relied on the AI).</li><li>Add up to two new rules you now need (for example about agents, keys or tests).</li><li>Keep the final list to seven rules or fewer, each one sentence you&#39;d actually follow.</li></ol><p>Submit the revised list on Canvas. It stays private; it&#39;s never committed to a repo. You&#39;ll also paste it into your final reflection.</p><h3 id="4-write-your-final-reflection-about-15-h-after-the-fair" tabindex="-1">4. Write your final reflection (about 1.5 h, after the Fair) <a class="header-anchor" href="#4-write-your-final-reflection-about-15-h-after-the-fair" aria-label="Permalink to &quot;4. Write your final reflection (about 1.5 h, after the Fair)&quot;">​</a></h3><p>🔴 <strong>AI off.</strong> Write it yourself, 400–600 words, and submit it on Canvas, never in your repo. Use <a href="./../../templates/REFLECTION.html">REFLECTION.md template</a> as a starting shape, but this one has a specific job:</p><p><strong>Compare how much you <em>felt</em> you understood while building with what you could <em>actually explain</em> afterward.</strong></p><p>Before you write, look back at your pre-course and post-course self-assessments on Canvas, your weekly reflections (including the moments you noted in week 15) and your Fair feedback cards: what visitors found after you froze <code>v1.0</code> is evidence too. Anchor the reflection in concrete moments across the course (a prompt, a commit, an error, a walkthrough question, an agent claim you checked, the AI-off maintenance task):</p><ol><li>A time you felt you understood something but couldn&#39;t explain it later (in a walkthrough, or while fixing a bug).</li><li>A time it went the other way: you doubted yourself, but could explain it fine.</li><li>One habit from the Safe Loop that changed how you work.</li><li><strong>Your revised personal AI-use rules.</strong> Paste the rules you wrote in week 2, then your revised version, and explain one rule you changed and why.</li><li>What you&#39;d tell a friend starting this course.</li></ol><p>Grading: the <a href="./../../assessment/rubrics.html#reflections-and-peer-reviews">final reflection rubric</a>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Supabase free projects pause when nobody uses them (<a href="./../../TOOLS.html">Tool Handout</a>). Restore yours before you submit and check the production URL still works.</p></div><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>The Fair can&#39;t be in person:</strong> your instructor runs the <a href="./project-fair.html#onlinehybrid-variant">online and hybrid variant</a>.</li><li><strong>Your app won&#39;t load at the Fair:</strong> play your demo video and let visitors try it afterward from the production URL. Then fix it, or name it in Known issues.</li><li><strong>Supabase paused:</strong> restore it from the dashboard (<a href="./../../resources/troubleshooting.html#supabase">Troubleshooting: Supabase</a>). Restoring can take a while, which is why you open it the day before.</li><li><strong>Vercel or Supabase is down at the deadline:</strong> submit anyway with the screenshot and the demo video, and tell your instructor. The rubric doesn&#39;t grade the vendor.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><p><strong>Keep going: a roadmap after the course.</strong> You now have the loop and the trust boundary. Tools will change; those won&#39;t. Where to go next, roughly in order:</p><ol><li><strong>Ship one more thing you&#39;ll use.</strong> The fastest way to keep the skill is to build something small and real, start to finish, on your own.</li><li><strong>Deepen the fundamentals</strong> the oral walkthroughs stretched: reading errors, explaining functions, writing tests, git branches and reverts. These are what let you go faster with AI, not slower (<a href="./../../research/landscape-report-2026-09.html">September report</a>).</li><li><strong>Learn the next rung when you need it</strong>, not before. A background or cloud agent, MCP servers, GitHub Actions, a framework: pick these up on a project that needs them.</li><li><strong>Keep up without chasing every tool.</strong> Follow a few signal sources; when a free tier changes, switch to a fallback (you&#39;ve practiced this). The open standards, <strong>AGENTS.md, MCP and git</strong>, are the safe bet.</li><li><strong>Stay safe by habit:</strong> privacy settings on new tools, secrets on the server, grants and RLS together on every table, read the diff, approvals on, check packages. The week 14 security checklist works on any project.</li><li><strong>Keep a portfolio.</strong> Leave your repos public with good READMEs and demo videos, if you&#39;re comfortable. That&#39;s your proof that you can direct AI to build real, explainable software.</li></ol><p>More: <a href="./../../resources/reading-list.html">Reading List</a>.</p><p>Congratulations: you built, secured, shipped and can explain real software. That&#39;s the whole course.</p>',59)])])}const p=t(s,[["render",n]]);export{f as __pageData,p as default};
